pragma solidity >=0.8.0;

contract FixedBytesCastProbe {
    bytes1 public lastB1;
    bytes16 public lastB16;

    function cast(bytes32 x) external returns (bytes1) {
        lastB1 = bytes1(x);
        lastB16 = bytes16(x);
        return bytes1(x);
    }

    function widen(bytes16 v) external returns (bytes32) {
        return bytes32(v);
    }
}
